import{_ as e,o as s,c as a,ag as i}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Part 15 — Cryptography & Security Primitives","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_15_Crypto.md","filePath":"todo/study_plan/parts/Part_15_Crypto.md"}'),d={name:"todo/study_plan/parts/Part_15_Crypto.md"};function r(n,t,o,l,c,h){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="part-15-—-cryptography-security-primitives" tabindex="-1">Part 15 — Cryptography &amp; Security Primitives <a class="header-anchor" href="#part-15-—-cryptography-security-primitives" aria-label="Permalink to &quot;Part 15 — Cryptography &amp; Security Primitives&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 8 (shared with Parts 16, 17). <strong>Budget: ~3-4 hrs.</strong></p></blockquote><h2 id="_15-cryptography-security-primitives-—-topic-inventory" tabindex="-1">15 Cryptography &amp; Security Primitives — topic inventory <a class="header-anchor" href="#_15-cryptography-security-primitives-—-topic-inventory" aria-label="Permalink to &quot;15 Cryptography &amp; Security Primitives — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Symmetric encryption — AES (modes: GCM, CBC, CTR), ChaCha20-Poly1305</td><td>🔴 💼 🔐</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>2</td><td>Asymmetric encryption — RSA, ECC, key sizes</td><td>🔴 💼 🔐</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Hash functions — SHA-2 family, SHA-3, properties (preimage, collision)</td><td>🔴 💼 🔐</td><td>MP</td><td>1 hr 50 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: SHA-256 a string via Java MessageDigest from memory + verify with <code>echo -n &quot;hello&quot; | shasum -a 256</code> (10 min)</td></tr><tr><td>4</td><td>MAC — HMAC, vs digital signature</td><td>🔴 💼 🔐</td><td>MP</td><td>1 hr 40 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: Java HMAC-SHA256 over a payload with shared secret + verify equality timing-safely (10 min)</td></tr><tr><td>5</td><td>Authenticated encryption (AEAD) — AES-GCM, why not raw CBC</td><td>🔴 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>Key derivation — PBKDF2, scrypt, Argon2, HKDF</td><td>🔴 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>SQL injection, parameterized queries</td><td>🔴 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>XSS — reflected, stored, DOM</td><td>🔴 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>CSRF</td><td>🔴 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Replay attacks — timestamps, nonces</td><td>🔴 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>Timing attacks, constant-time comparison</td><td>🔴 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>Random number generation — CSPRNG, /dev/urandom, SecureRandom</td><td>🟠 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>Password hashing — never SHA-256 plain, use Argon2 / bcrypt</td><td>🟠 💼 🔐</td><td>MP</td><td>1 hr 35 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: Argon2id hash + verify in Java (Spring Security&#39;s BCryptPasswordEncoder + Argon2 via Bouncy Castle); compare hash output (20 min)</td></tr><tr><td>14</td><td>Nonce, IV — reuse pitfalls (catastrophic for GCM)</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>SSRF</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>Padding oracle (CBC)</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>17</td><td>Side-channel</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>18</td><td>Insecure deserialization</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>19</td><td>Supply chain (log4shell era)</td><td>🟠 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>20</td><td>Diffie-Hellman, ECDH key exchange</td><td>🟡 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>21</td><td>OWASP Top 10 — full list</td><td>🟠 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~17.5 hrs</td><td>~1.6 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~28.85 hrs</td><td>~2.6 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~30.35 hrs</td><td>~2.75 wk</td><td></td></tr></tbody></table><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>AEAD decision tree:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Start[&quot;What do you need?&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C{&quot;Confidentiality&lt;br/&gt;only?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I{&quot;Integrity&lt;br/&gt;only?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B{&quot;Both&lt;br/&gt;(almost always)?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CONF[&quot;AES-CTR or ChaCha20&lt;br/&gt;(rare — only when integrity&lt;br/&gt;is enforced elsewhere)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    INT[&quot;HMAC-SHA256&lt;br/&gt;(MAC, no encryption)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AEAD[&quot;AEAD:&lt;br/&gt;AES-GCM (FIPS, hardware-accel)&lt;br/&gt;or ChaCha20-Poly1305 (mobile)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Start --&gt; C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|yes| CONF</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|no| I</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I --&gt;|yes| INT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I --&gt;|no| B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|yes| AEAD</span></span></code></pre></div><blockquote><p>Encrypt-then-MAC is the safe composition; AEAD does this for you. If you&#39;re typing <code>Cipher.getInstance(&quot;AES/CBC/...&quot;)</code> in 2026, stop — use GCM.</p></blockquote><p><strong>Envelope encryption (cryptographic primitive view):</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    autonumber</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant App</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant KMS as Key Management</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Store as Storage</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over App,KMS: Encrypt path</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;KMS: GenerateDataKey(KEK_id)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    KMS--&gt;&gt;App: (plaintext DEK, encrypted DEK)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;App: ciphertext = AES-GCM(DEK, plaintext, nonce)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;App: wipe plaintext DEK from memory</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;Store: store (ciphertext, nonce, encrypted DEK)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over App,KMS: Decrypt path</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;Store: fetch (ciphertext, nonce, encrypted DEK)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;KMS: Decrypt(encrypted DEK, KEK_id)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    KMS--&gt;&gt;App: plaintext DEK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    App-&gt;&gt;App: plaintext = AES-GCM⁻¹(DEK, ciphertext, nonce)</span></span></code></pre></div><blockquote><p>The KEK never leaves the KMS boundary. Only the per-object DEK touches the application heap, and only briefly. Rotation = re-wrap the DEK with a new KEK; no payload re-encryption needed.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> AES-GCM vs AES-CBC — why is GCM preferred for new code? <ul><li><strong>Why asked:</strong> Senior crypto choice. GCM is AEAD — authenticated encryption with associated data. Provides both confidentiality AND integrity in one primitive. CBC alone is unauthenticated → vulnerable to padding oracle, manipulation. Using CBC requires HMAC on top (encrypt-then-MAC, easy to get wrong). GCM does it correctly by design.</li></ul></li><li><strong>Q:</strong> Why is password hashing different from generic hashing? What makes Argon2 better than SHA-256? <ul><li><strong>Why asked:</strong> Senior security. SHA-256 is fast — too fast (GPUs can crack billions/sec). Password hashing must be SLOW + memory-hard. Argon2id is the modern winner: configurable time, memory, parallelism cost. bcrypt is older but still acceptable. PBKDF2 is fallback (FIPS-compliant). Never SHA-256 alone for passwords.</li></ul></li><li><strong>Q:</strong> HMAC vs digital signature — when does each fit? <ul><li><strong>Why asked:</strong> Crypto primitive choice. HMAC: shared secret, symmetric, fast. Both parties hold the key. Use: webhook signing, JWT (HS256), API request signing. Digital signature: private key signs, public key verifies. Asymmetric. Use: code signing, document signing, JWT (RS256), TLS certificates.</li></ul></li><li><strong>Q:</strong> What&#39;s a timing attack? Show me an example where you&#39;d use constant-time comparison. <ul><li><strong>Why asked:</strong> Subtle senior gotcha. Comparing secrets byte-by-byte (Java <code>String.equals()</code> or <code>Arrays.equals()</code>) leaks timing info — attacker measures how many bytes match. Use <code>MessageDigest.isEqual(a, b)</code> or <code>Arrays.equals(...)</code> of fixed-length data in constant time. Critical for: HMAC verification, password comparison, token comparison.</li></ul></li><li><strong>Q:</strong> Walk through a CSRF attack and how to prevent it. <ul><li><strong>Why asked:</strong> Web security basics. Attacker tricks user&#39;s browser to send a request to a target site where the user is authenticated (via session cookie). Prevention: (1) SameSite=Strict cookies (modern browsers), (2) CSRF tokens (random token per session, validated server-side), (3) Origin / Referer header checks, (4) require explicit re-auth for sensitive operations.</li></ul></li><li><strong>Q:</strong> Padding oracle attack — what&#39;s the prerequisite, and how do you defeat it? <ul><li><strong>Why asked:</strong> Senior security. Prerequisite: server uses CBC without authentication AND reveals padding-validity info (e.g., 400 for bad padding, 500 for decryption error). Attacker can decrypt ciphertext byte-by-byte by submitting modified ciphertexts. Defeat: use AEAD (AES-GCM) → no padding oracle possible.</li></ul></li><li><strong>Q:</strong> Nonce reuse in AES-GCM — how catastrophic, and how do you prevent it? <ul><li><strong>Why asked:</strong> Specific landmine. Catastrophic — reusing a nonce with the same key in GCM leaks the authentication key, letting attackers forge messages. Prevention: random 96-bit nonces (collision probability ≈ 2^-48 after 2^32 encryptions), OR strictly monotonic counter, OR derive nonce from session ID.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> You used <code>String.equals(suppliedToken, expectedToken)</code> to verify an API token. What&#39;s the security issue? <ul><li><strong>Gotcha:</strong> Timing leak. <code>String.equals</code> short-circuits on first mismatched byte. Attacker can guess tokens byte-by-byte by measuring response time. Fix: <code>MessageDigest.isEqual(supplied.getBytes(), expected.getBytes())</code> for constant-time comparison.</li></ul></li><li><strong>Q:</strong> You hashed passwords with <code>MessageDigest.SHA256</code> + a salt. Why is this still insecure? <ul><li><strong>Gotcha:</strong> SHA-256 is computationally cheap. With salt, you defeat rainbow tables, but a determined attacker with GPUs can still try billions of guesses/sec. Use Argon2id (or bcrypt minimum) — designed to be intentionally slow + memory-hard.</li></ul></li><li><strong>Q:</strong> You generated a 256-bit AES key from <code>new Random().nextBytes(...)</code>. What&#39;s wrong? <ul><li><strong>Gotcha:</strong> <code>java.util.Random</code> is a PRNG (predictable). Use <code>SecureRandom</code> (CSPRNG) for any cryptographic material. Worse: don&#39;t seed <code>SecureRandom</code> from <code>Random</code> — that defeats the purpose.</li></ul></li><li><strong>Q:</strong> Why does AES-GCM require unique nonces, but AES-CBC doesn&#39;t (mostly)? <ul><li><strong>Gotcha:</strong> GCM uses counter mode internally — reusing nonce reveals XOR of plaintexts AND leaks authentication key. CBC reusing IV reveals XOR equality of first blocks (a weakness, but recoverable). GCM nonce reuse is catastrophic; CBC IV reuse is bad-but-survivable.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>AEAD + AES-GCM end-to-end</strong> (~3 hrs rows 1 + 5 + 14) — when to use, why GCM beat CBC, nonce hygiene, key rotation strategy. Connect to Part 13 KMS envelope encryption.</li><li><strong>Password hashing with Argon2id</strong> (~2 hrs row 13) — directly application security. Spring Security&#39;s encoder factory pattern + parameter tuning (memory, time, parallelism).</li><li><strong>Webhook signing pattern</strong> (~2.5 hrs row 4 + row 10 + row 11) — HMAC + timestamp + constant-time comparison. Production-grade implementation for your KYC partner integration.</li><li><strong>Common attack catalog</strong> (~3 hrs combined rows 7-19) — walk through each attack with example + defense. Pair with code review of your KYC platform for these issues.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up crypto exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>AES-GCM encrypt + decrypt + verify integrity</strong> (~60 min) — Java <code>Cipher.getInstance(&quot;AES/GCM/NoPadding&quot;)</code> with <code>SecureRandom</code> nonce + 256-bit key. Encrypt a payload, decrypt successfully, then flip a bit of ciphertext and observe <code>AEADBadTagException</code>.</li><li><strong>HMAC-SHA256 webhook signer + verifier</strong> (~60 min) — sender computes HMAC over <code>timestamp + body</code> using shared secret, attaches as <code>X-Signature</code> header. Receiver verifies in constant time + checks timestamp window. Tests: tampered body, expired timestamp, swapped signature.</li><li><strong>Argon2id password hash with adjustable parameters</strong> (~45 min) — Spring Security&#39;s <code>Argon2PasswordEncoder</code>. Hash a password with default + with stronger params (more memory + iterations). Measure hashing time. Verify rejected match.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Build an envelope-encryption scheme</strong> (~90 min) — generate 256-bit DEK per file, encrypt file with AES-GCM, encrypt DEK with a &quot;master key&quot; (locally for the exercise, KMS in prod). Store <code>(encrypted_payload + encrypted_dek + nonce + iv)</code>. Implement decrypt path. Document the threat model.</li><li><strong>Reproduce a timing attack on token comparison</strong> (~60 min) — service that compares API tokens with <code>equals()</code>. Write a client that measures response time for guesses. Plot timing differences. Then swap to <code>MessageDigest.isEqual</code> and confirm timing flat.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5.25 hrs</strong></td><td><strong>~0.48 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~40 min for Part 15 across 3 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. AEAD — what does it guarantee?</strong> A. Authenticated Encryption with Associated Data — confidentiality (encrypted) + integrity (tampering detected) + authenticity (came from key-holder) + optional bound metadata. AES-GCM is the standard AEAD.</p><p><strong>Q. AES-GCM nonce reuse — how bad?</strong> A. Catastrophic. Reuse leaks authentication key, allowing forgery. Always use unique nonces — random 96-bit or strict counter.</p><p><strong>Q. Password hashing — why not SHA-256?</strong> A. SHA-256 is fast. Attackers crack billions of guesses per second on GPUs. Password hashing must be slow + memory-hard — use Argon2id (or bcrypt minimum).</p><p><strong>Q. HMAC vs digital signature — one-line distinction.</strong> A. HMAC: symmetric (shared secret), both sides hold the same key. Digital signature: asymmetric (private signs, public verifies); useful when verifier shouldn&#39;t be able to forge.</p><p><strong>Q. Constant-time comparison — when required?</strong> A. Comparing secrets: HMAC verification, token comparison, password verification. Standard string <code>equals()</code> short-circuits → timing leak. Use <code>MessageDigest.isEqual()</code>.</p><p><strong>Q. CSRF — three defenses.</strong> A. (1) <code>SameSite=Strict</code> cookies (modern default). (2) CSRF tokens per session (validated server-side). (3) Verify Origin / Referer header for state-changing requests.</p>`,35)])])}const m=e(d,[["render",r]]);export{g as __pageData,m as default};
